D={}
D['santana']=dict(desc='Santāna Lakṣmī, Lakṣmī of children and family: her six-armed form with a child on her lap, the Śrī Sūkta’s Kardama, Varalakṣmī Vratam and Cārumatī’s story, Santāna Gopāla, and family as wealth.',
 tag='Lakṣmī of children and family',fwq=("Children are wealth?","Ask any grandparent. The family is the treasure."),
 fw=['<b>Santāna</b> means offspring, continuity, the line that carries on. Santāna Lakṣmī holds a child on her lap: she is Lakṣmī as the blessing of children, of a healthy family and of generations that continue.',
     'This guide traces her from a Vedic verse about Śrī’s son Kardama to the Varalakṣmī Vratam that women keep across the South, and asks what “family wealth” really means.'],
 pages=[('glance','AT A GLANCE','Santāna Lakṣmī on one page',[('Name','Santāna Lakṣmī, “Lakṣmī of offspring”'),('Gift','Children, their health, and a family that continues'),('Form','Six arms: two pots (kalaśa), a sword and a shield; one hand holding a child on her lap, one in fear-not'),('Feel','The most motherly of the eight'),('Prayed to','By couples hoping for children, and parents for their children’s welfare')],("Why a sword and shield, with a baby?","A mother protects. That's the most fierce love there is.")),
  ('kardama','KARDAMA, ŚRĪ’S SON','In the Śrī Sūkta',[('The verse','“By Kardama, Śrī has offspring; dwell in me, Kardama”'),('Kardama','Called Śrī’s son, “mud”, the fertile earth from which life grows'),('Ciklīta','Another son of Śrī in the hymn, asked to bring her home'),('Meaning','Even the Vedic Śrī is a mother')],None,'<div class="verse"><p><i>kardamena prajā bhūtā mayi sambhava kardama<br>śriyaṃ vāsaya me kule mātaraṃ padmamālinīm</i></p><p class="small">Through Kardama she has offspring; Kardama, dwell in me; make Śrī, the Mother wearing a lotus garland, live in my family.</p></div>'),
  ('vrata','VARALAKṢMĪ VRATAM','The family vow',[('When','The Friday before the full moon of Śrāvaṇa (July–August)'),('Who','Mainly married women, for husband, children and home'),('Kalaśa','A pot dressed as the Goddess, with a coconut face, sari and jewels'),('Thread','A sacred yellow thread (dāra, toraṇa) is tied on the wrist'),('Where','Karnataka, Andhra, Telangana, Tamil Nadu, Maharashtra')],("Is that Santāna Lakṣmī?","It's Lakṣmī as Vara, the boon-giver. The boon most asked is the family's welfare.")),
  ('charumati','CĀRUMATĪ’S STORY','The vrata legend',[('Śiva to Pārvatī','The vrata story is told by Śiva to Pārvatī, in a text ascribed to the Skanda Purāṇa'),('Cārumatī','A devoted wife in the town of Kuṇḍina'),('The dream','Lakṣmī appeared and taught her the vrata'),('Blessing','She and the women who kept it with her were blessed with wealth and family')]),
  ('gopala','SANTĀNA GOPĀLA','Kṛṣṇa as the child-giver',[('Mantra','A well-known mantra to Kṛṣṇa as Santāna Gopāla, said by couples wishing for a child'),('Image','Baby Kṛṣṇa on Yaśodā’s lap: the matching picture'),('Ṣaṣṭhī','The goddess Ṣaṣṭhī and Subrahmaṇya are also prayed to for children'),('Together','Lakṣmī and Viṣṇu as parents of the world')],None,'<div class="key">See: <a href="/bhakti/shiva/subrahmanya-shashthi/">Subrahmaṇya Ṣaṣṭhī</a></div>'),
  ('stotram','HER VERSE','In the Aṣṭalakṣmī Stotram',[('Theme','Her verse calls her the mother of the world, giver of children'),('Feel','Gentle, a lullaby beside the war-cry of Dhairya Lakṣmī'),('Refrain','It asks her to protect the singer always'),('Use','Sung by expectant parents and at naming ceremonies')]),
  ('family','FAMILY AS WEALTH','What santāna means',[('Continuity','Santāna also means an unbroken line: the family’s values passed on'),('Health','Children’s wellbeing, not only their birth'),('Adoption','Tradition honours adopted and foster children as fully one’s own: Kṛṣṇa raised by Yaśodā'),('Students','In some traditions, disciples are called spiritual offspring')],("What about families without children?","Santāna is more than birth. Nephews, students, the young you raise: all are family.")),
  ('care','A NOTE ON CARE','Prayer and medicine',[('Fertility','Many couples pray and also seek medical help; the two go together'),('Pregnancy','Prayers for a safe birth sit beside good antenatal care'),('Compassion','No one should be blamed for not having children'),('Her way','Santāna Lakṣmī is a mother, not a judge')]),
  ('meaning','WHAT SHE TEACHES','The treasure at home',[('Protect the young','Her sword and shield'),('Raise well','A family is a line of values'),('Every child','Born or adopted, a gift'),('Gratitude','Count the people around your table')]),
 ],
 end=[('Who','Lakṣmī of children and family'),('Roots','The Śrī Sūkta’s Kardama; Lakṣmī as Mother'),('Vow','Varalakṣmī Vratam and Cārumatī'),('Kin','Santāna Gopāla, Ṣaṣṭhī'),('Lesson','The family is the treasure: protect and raise it well')],endq=("One line?","A child on her lap and a sword in her hand. That's motherhood."),
 src='Śrī Sūkta (Kardama verse); Varalakṣmī Vrata Kathā (ascribed to the Skanda Purāṇa); Bhāgavata Purāṇa 10 (Kṛṣṇa and Yaśodā); Aṣṭalakṣmī temple iconography.',
 unv='The Skanda Purāṇa ascription of the vrata story is traditional; the Śrī Sūkta’s later verses (including Kardama) are considered later additions to the khila.',
 EX={'glance':['Santāna Lakṣmī is the form most often prayed to quietly, by couples longing for a child or parents anxious for a sick one. Her image combines tenderness and protection: a baby on her lap, a sword and shield in her hands.','Her pots, kalaśas, are full: fertility, the womb, abundance. Many homes keep her picture in the room of an expectant mother.'],
  'kardama':['The later verses of the Śrī Sūkta speak to Śrī’s children, Kardama and Ciklīta, asking them to bring their mother to live in the singer’s family. Kardama literally means mud or clay: the fertile wet earth from which crops and life spring.','The Purāṇas also know a sage Kardama, father of nine daughters and of the philosopher Kapila. Whatever the link, the hymn makes Śrī a mother whose presence in a family is its fortune.'],
  'vrata':['Varalakṣmī Vratam is one of the most important domestic festivals of the South. Women prepare for days: the house is cleaned, the kalaśa is decorated with a coconut, mango leaves, turmeric and a silver or painted face of the Goddess, and the vrata story is read.','The sacred thread tied on the wrist (in Kannada often called dāra) is a vow and a protection. Neighbours are invited and given turmeric, kumkum and small gifts, a sign of shared good fortune.'],
  'charumati':['In the vrata story, Śiva tells Pārvatī of Cārumatī, a woman of Kuṇḍina devoted to her husband and in-laws. Lakṣmī, pleased, appears in a dream and teaches her the vrata. Cārumatī performs it with her neighbours, and all are blessed.','The story makes devotion to family, not wealth itself, the reason for Lakṣmī’s blessing. That is the heart of Santāna Lakṣmī.'],
  'gopala':['Santāna Gopāla, Kṛṣṇa as giver of children, is a widely used devotional mantra. Couples also pray to Ṣaṣṭhī, the goddess of the sixth day, protector of newborns, and to Subrahmaṇya, especially in Karnataka at Kukke and Ghāṭi.','The image of baby Kṛṣṇa on Yaśodā’s lap matches Santāna Lakṣmī’s: the divine child and the loving mother.'],
  'stotram':['Her verse in the Stotram has a soft, rocking rhythm. It is often sung by grandmothers to newborns, and at nāmakaraṇa, naming ceremonies.','We describe it rather than reproduce it.'],
  'family':['Santāna means more than offspring. It is the continuity of a family: its name, values, skills and memory. A family that passes on good habits, the tradition says, keeps Santāna Lakṣmī.','Indian epics honour adoptive and foster parents warmly: Kṛṣṇa raised by Yaśodā and Nanda, Karṇa by Adhiratha and Rādhā, Sītā found in a furrow by Janaka.'],
  'care':['Prayers for children have always sat beside practical care. Today that means medical help for infertility and safe pregnancy. Faith and medicine are not rivals here.','A compassionate reading of Santāna Lakṣmī also rejects blaming women, or anyone, for not having children. She is a mother, and mothers comfort.'],
  'meaning':['Santāna Lakṣmī asks us to treat family as wealth: to protect the young fiercely, to raise them with values, and to see every child, born or adopted, as a gift.','The simplest practice is gratitude: to look around the dinner table and count the blessings there.']})
D['vijaya']=dict(desc='Vijaya Lakṣmī (Jaya Lakṣmī), Lakṣmī of victory: her eight-armed red form with discus, conch, sword and shield; Vijayadaśamī and Mysuru Dasara, Arjuna called Vijaya, Rāja Lakṣmī on Gupta coins, and the city of Vijayanagara.',
 tag='Lakṣmī of victory',fwq=("Victory over what?","Over enemies, over obstacles, and over yourself."),
 fw=['<b>Vijaya</b> means victory. Vijaya Lakṣmī, also called Jaya Lakṣmī, is the Goddess of success: winning a battle, a case, an exam or a hard inner struggle.',
     'This guide follows victory through Indian tradition: Vijayadaśamī, Mysuru’s great Dasara, Arjuna whose name was Vijaya, the royal Lakṣmī on Gupta coins, and Karnataka’s own “city of victory”, Vijayanagara.'],
 pages=[('glance','AT A GLANCE','Vijaya Lakṣmī on one page',[('Name','Vijaya Lakṣmī, also Jaya Lakṣmī: “Lakṣmī of victory”'),('Gift','Success, victory and overcoming obstacles'),('Form','Red sari; eight arms with discus, conch, sword, shield, lotus and noose; boon and fear-not gestures'),('Seated','Often on a lotus, sometimes shown with an elephant'),('Prayed to','Before contests, exams, interviews and court cases')],("Is it OK to pray to win?","For a fair fight, yes. Victory over wrong is her gift.")),
  ('vijayadashami','VIJAYADAŚAMĪ','The day of victory',[('When','The tenth day of Āśvina’s bright fortnight, after Navarātri'),('Stories','Rāma’s victory over Rāvaṇa; Durgā’s over Mahiṣa; the Pāṇḍavas taking back their weapons from the śamī tree'),('Śamī','Leaves of the śamī tree are exchanged as “gold”'),('New beginnings','Children start school (vidyārambha); work and journeys begin')]),
  ('dasara','MYSURU DASARA','Karnataka’s great victory festival',[('Nāḍa Habba','Karnataka’s state festival'),('Cāmuṇḍeśvarī','The Goddess of Mysuru, slayer of Mahiṣa, is taken in a golden howdah on an elephant'),('Jambū Savārī','The great procession on Vijayadaśamī'),('Since','Kept with royal splendour since the Vijayanagara and Wodeyar kings')],("Why Mysuru?","Mahiṣa's town, by tradition: Mahiṣūru. Victory over him is the city's story.")),
  ('arjuna','ARJUNA, “VIJAYA”','The victorious one',[('Name','One of Arjuna’s ten names is Vijaya, because he always won'),('Gītā','Arjuna says: I want no victory, Kṛṣṇa (na kāṅkṣe vijayaṃ, 1.32)'),('Last verse','The Gītā ends: where Kṛṣṇa and Arjuna are, there are Śrī, victory (vijaya), prosperity and justice (18.78)'),('Meaning','Victory follows dharma and skill together')],None,'<div class="key">See: <a href="/bhakti/vishnu/bhagavad-gita/chapter-18/#v78">Gītā 18.78</a></div>'),
  ('rajya','RĀJA LAKṢMĪ','Fortune of kings',[('Kingship','Lakṣmī was the king’s fortune: if she left, the kingdom fell'),('Gupta coins','Gold coins show the king with Lakṣmī on the reverse'),('Coronation','The abhiṣeka bath, like Gaja Lakṣmī’s'),('Vijaya and Rājya','Some lists name Rājya Lakṣmī; others fold her into Vijaya')]),
  ('vijayanagara','VIJAYANAGARA','Karnataka’s city of victory',[('Name','“City of Victory”, capital at Hampi from the 14th to 16th century'),('Founded','By Harihara and Bukka, traditionally with the blessing of the sage Vidyāraṇya'),('Gods','Virūpākṣa its guardian; Lakṣmī Narasiṃha, Viṭhṭhala and Rāma among its great shrines'),('Legacy','The Mysuru Dasara continues its Mahānavamī tradition')]),
  ('stotram','HER VERSE','In the Aṣṭalakṣmī Stotram',[('Theme','Her verse calls her victorious, worshipped by all, giver of knowledge and liberation'),('Tone','Triumphant, like a victory song'),('Refrain','It asks her to protect the singer always'),('Use','Before exams, contests and new ventures')]),
  ('inner','THE INNER VICTORY','Over oneself',[('Gītā 6.6','The self is friend to one who has conquered himself'),('Anger and greed','The six inner enemies are the hardest foes'),('Jaya','The epic itself was first called Jaya, “Victory”'),('Quiet wins','Keeping a promise, breaking a bad habit')],("Is that also Vijaya Lakṣmī?","The biggest victory of all, the teachers say.")),
  ('meaning','WHAT SHE TEACHES','Win rightly',[('Effort and grace','Victory needs both'),('Fair means','Victory by wrong means is not her gift'),('Humility in winning','Rāma honoured Rāvaṇa in death'),('Beginnings','Every new start is a small victory')]),
 ],
 end=[('Who','Lakṣmī of victory, also Jaya Lakṣmī'),('Days','Vijayadaśamī; Mysuru Dasara'),('Figures','Arjuna “Vijaya”; Rāja Lakṣmī; Vijayanagara'),('Inner','Victory over oneself is the greatest'),('Lesson','Win rightly, and win with grace')],endq=("One line?","Where dharma and skill meet, there victory lives."),
 src='Bhagavad Gītā 1.32, 6.6, 18.78; Mahābhārata, Virāṭa Parva (Arjuna’s ten names); Gupta numismatics; Karnataka Tourism and Mysuru Palace Board on Dasara; histories of Vijayanagara.',
 unv='Her weapons vary by image; Vidyāraṇya’s role in the founding of Vijayanagara is traditional and debated by historians; the identification of Mysuru with Mahiṣa’s town is traditional.',
 EX={'glance':['Vijaya Lakṣmī is close to Dhairya Lakṣmī, courage, and to Gaja Lakṣmī, royal power. Where courage is the means, victory is the result. Her weapons are those of the warrior Goddess.','She is prayed to before any contest, from a cricket match to a court hearing. Tradition adds a condition: she blesses fair fights.'],
  'vijayadashami':['Vijayadaśamī gathers several victory stories into one day. In the Mahābhārata tradition, the Pāṇḍavas hid their weapons in a śamī tree during their year in disguise and recovered them on this day before the battle against the Kauravas’ cattle raid.','In Karnataka and Maharashtra, śamī (bannī) leaves are exchanged as “gold” with greetings. The day is also auspicious for beginning studies and new ventures.'],
  'dasara':['Mysuru Dasara is Karnataka’s Nāḍa Habba, state festival. Its climax, the Jambū Savārī, carries Goddess Cāmuṇḍeśvarī in a golden howdah on an elephant through the city on Vijayadaśamī, followed by the torchlight parade.','The festival’s royal style continues the Mahānavamī celebrations of the Vijayanagara kings, which foreign visitors to Hampi described in wonder in the 16th century.'],
  'arjuna':['In the Virāṭa Parva, Arjuna explains his ten names to Prince Uttara. He is Vijaya because he never returned from battle without winning.','The Gītā’s last verse, spoken by Sañjaya, names victory with Śrī: where Kṛṣṇa, the master of yoga, and Arjuna, the archer, are together, there are fortune, victory, prosperity and justice. It is often taken as the Gītā’s own blessing.'],
  'rajya':['In classical Indian political thought, the king’s fortune, rājalakṣmī or rājyaśrī, was a goddess who chose a king and could abandon him. Poets wrote of her as a fickle beloved who must be kept by righteous rule.','Gupta gold coins, among the finest of ancient India, often show Lakṣmī on the reverse, sometimes holding a cornucopia or lotus, as the king’s fortune.'],
  'vijayanagara':['Vijayanagara, founded in the 14th century, became one of the great cities of the world. Its name announced its purpose. Its temples at Hampi, Virūpākṣa, Viṭhṭhala, Hazāra Rāma and the giant monolithic Lakṣmī Narasiṃha, are now a UNESCO World Heritage Site.','The Wodeyars of Mysuru, once Vijayanagara’s feudatories, carried on its Dasara, which is why Mysuru’s celebration has imperial roots.'],
  'stotram':['Her verse in the Stotram is triumphant, with drums and conches in its sounds. Students often recite it on exam mornings.','We describe rather than reproduce it.'],
  'inner':['The Gītā says that for one who has conquered the self, the self is a friend; for one who has not, it acts like an enemy (6.6). The traditional six inner enemies, lust, anger, greed, delusion, pride and envy, are the hardest to defeat.','The Mahābhārata itself, scholars note, was once known as Jaya, “Victory”, and its invocation verse still ends with that word.'],
  'meaning':['Vijaya Lakṣmī teaches that victory is a gift and a responsibility: won through effort and grace, by fair means, and carried with humility. Rāma ordered full funeral honours for Rāvaṇa: enmity ends with death.','Every beginning, a new school year, a new job, is a small victory, which is why Vijayadaśamī is a day for starting things.']})
for i,k in [(4,'santana'),(5,'vijaya')]: FORM(i,D[k])
